def stopfree(s, strand):
    # return list of (start,end) 0-based half-open in forward coords, stop-free in-frame stretches >150
    res=[]
    L=len(s)
    for f in range(3):
        # find stop positions (in s coords)
        stopidx=[j for j in range(f, L-2, 3) if s[j:j+3] in stops]
        bounds=[f-3]+stopidx+[L]
        for a,b in zip(bounds, bounds[1:]):
            seg_len=b-(a+3)
            if seg_len>=150:
                if strand==1:
                    res.append((a+3,b,seg_len))
                else:
                    res.append((n-b, n-(a+3), seg_len))
    return res

